effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat12;
vec2 u_xlat13;
float u_xlat18;
bool u_xlatb18;
void main()
{
    u_xlat0.x = _direction + 90.0;
    u_xlat0.x = u_xlat0.x * 0.0174532942;
    u_xlat1.x = sin((-u_xlat0.x));
    u_xlat1.y = cos(u_xlat0.x);
    u_xlat0.x = _cur_time * _speed;
    u_xlat0.xy = acScreenNorm.xy * vec2(20.0, 20.0) + u_xlat0.xx;
    u_xlat0.xy = sin(u_xlat0.xy);
    u_xlat12.xy = u_xlat0.xy * u_xlat0.xy;
    u_xlat0.xy = u_xlat12.xy * u_xlat0.xy;
    u_xlat2.w = 1.0;
    u_xlat3.x = float(0.0);
    u_xlat3.y = float(0.0);
    u_xlat3.z = float(0.0);
    u_xlat3.w = float(0.0);
    u_xlat12.x = 0.0;
    while(true){
        u_xlatb18 = u_xlat12.x>=1.0;
        if(u_xlatb18){break;}
        u_xlat18 = (-u_xlat12.x) + 1.0;
        u_xlat18 = u_xlat12.x * u_xlat18;
        u_xlat18 = log2(u_xlat18);
        u_xlat18 = u_xlat18 * 1.5;
        u_xlat18 = exp2(u_xlat18);
        u_xlat4.y = u_xlat18 * 6.80000019;
        u_xlat13.xy = u_xlat12.xx * u_xlat1.xy;
        u_xlat13.xy = u_xlat13.xy * vec2(_amplitude);
        u_xlat13.xy = u_xlat0.xy * u_xlat13.xy;
        u_xlat13.xy = u_xlat13.xy * vec2(0.100000001, 0.100000001) + acScreenNorm.xy;
        u_xlat4.xz = u_xlat12.xx * vec2(1.0, -1.0) + vec2(0.0, 1.0);
        u_xlat2.xyz = u_xlat4.xyz * u_xlat4.xyz;
        u_xlat4 = texture(inputImg, u_xlat13.xy);
        u_xlat3 = u_xlat2 * u_xlat4 + u_xlat3;
        u_xlat12.x = u_xlat12.x + 0.00999999978;
    }
    u_xlat0 = u_xlat3 * vec4(0.029555222, 0.0302767847, 0.0295551848, 0.00990098994);
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
